-- string.format: every directive, flags, width/precision, int64 cdata, errors.
local function e(...) print(pcall(...)) end
local F = string.format
print(F("%d %i %u", 42, -42, 42))
print(F("%5d|%-5d|%05d|%+d|% d|%.3d", 42, 42, 42, 42, 42, 7))
print(F("%d %d %d", 3.7, -3.7, 2^31), F("%d", 2^53), F("%d", -2^63), F("%d", 1e100))
print(F("%x %X %o %#x %#o %08x", 255, 255, 8, 255, 8, 255))
print(F("%x", -1), F("%u", -1), F("%x", 2^40))
print(F("%c%c%c", 76, 117, 97), F("%5c|%-5c|", 65, 66))
print(F("%e %E %.2e %10.3e", 12345.678, 0.001, 1e-10, -5))
print(F("%f %.0f %.10f %10.2f %-10.2f| %+f %#.0f", 3.14159, 2.5, 1/3, -2.5, 2.5, 1, 3))
print(F("%g %g %g %g %G %.3g %#g", 0.1, 1e20, 1e-5, 100000, 1e-20, 2/3, 1))
print(F("%a %A %.3a", 1, 255.5, 1/3))
print(F("%f %e %g %a %d", 1/0, -1/0, 0/0, 1/0, 0))
print(F("%5.1f|%-8.3s|%.2s|%10s", 3.14159, "abcdef", "xyz", "hi"))
print(F("%s %s %s %s", nil, true, false, 12.5))
print(F("%q", "a\nb\r\0c\"\\\1\127\200z"))
print(F("%q", 1/3), F("%q", 42))
print(F("%%"), F("100%%"), pcall(F, "%5%"))
print(F("%s", setmetatable({}, {__tostring = function() return "OBJ" end})))
print(F("%s|%s", setmetatable({}, {__tostring = function() return 42 end}), "x"))
print(F("%10s|", setmetatable({}, {__tostring = function() return "OBJ" end})))
print(F("%d %x %u|%X", 1LL, 18446744073709551615ULL, 9223372036854775808ULL, 0xdeadbeefULL), F("%5d|%-5d|%05x", 12LL, 3LL, 255ULL))
print(F("%.14g", 0.1), F("%.20f", 0.1), F("%.99f", 1):len())
print(F("abc"), F(""), F(123))
e(F)
e(F, "%d")
e(F, "%d", "x")
e(F, "%d", {})
e(F, "%s")
e(F, "%y", 1)
e(F, "%10.3q", "x")
e(F, "%123d", 1)
e(F, "%1.123d", 1)
e(F, "%", 1)
e(F, "%-", 1)
e(F, "%c", "x")
e(F, "%f", nil)
e(F, "%s %s", 1)
e(F, "%s", setmetatable({}, {__tostring = function() error("in tostring") end}))
print(select("#", F("%s %s", 1, 2, 3)))
